// @bun
// src/catalog.ts
var REASONING_LEVELS_CLIENT_VERSION = "1.0.0";
function normalizeBaseURL(value) {
  const url = new URL(value);
  const pathname = url.pathname.replace(/\/+$/, "");
  url.pathname = pathname.endsWith("/v1") ? pathname : `${pathname}/v1`;
  return url.toString().replace(/\/$/, "");
}
function parseCatalog(input) {
  if (!isRecord(input))
    throw new Error("CLIProxyAPI returned a non-object model catalog");
  const response = input;
  if (!Array.isArray(response.data))
    throw new Error("CLIProxyAPI model catalog is missing the data array");
  const models = response.data.map((item) => {
    if (!isRecord(item) || typeof item.id !== "string" || item.id.trim() === "")
      return;
    return {
      id: item.id,
      ...typeof item.owned_by === "string" ? { ownedBy: item.owned_by } : {}
    };
  }).filter((item) => item !== undefined);
  if (models.length === 0)
    throw new Error("CLIProxyAPI returned no usable models");
  const unique = new Map;
  for (const model of models) {
    if (!unique.has(model.id))
      unique.set(model.id, model);
  }
  return [...unique.values()];
}
function parseReasoningEffortCatalog(input) {
  if (!isRecord(input) || !Array.isArray(input.models))
    return {};
  const catalog = {};
  for (const item of input.models) {
    if (!isRecord(item) || typeof item.slug !== "string" || item.slug.trim() === "")
      continue;
    const rawLevels = item.supported_reasoning_levels;
    const levels = Array.isArray(rawLevels) ? rawLevels.map((entry) => isRecord(entry) && typeof entry.effort === "string" ? entry.effort : undefined).filter((level) => level !== undefined) : undefined;
    const limit = {};
    const context = [item.context_window, item.max_context_window].find(isPositiveNumber);
    const output = isPositiveNumber(item.max_tokens) ? item.max_tokens : undefined;
    if (context !== undefined)
      limit.context = context;
    if (output !== undefined)
      limit.output = output;
    const defaultLevel = levels && typeof item.default_reasoning_level === "string" ? item.default_reasoning_level : undefined;
    catalog[item.slug] = {
      ...levels ? { levels: [...new Set(levels)] } : {},
      ...defaultLevel ? { defaultLevel } : {},
      ...Object.keys(limit).length > 0 ? { limit } : {}
    };
  }
  return catalog;
}
async function discoverReasoningEfforts(input) {
  const response = await (input.fetcher ?? fetch)(`${input.baseURL}/models?client_version=${REASONING_LEVELS_CLIENT_VERSION}`, {
    headers: input.apiKey ? { Authorization: `Bearer ${input.apiKey}` } : undefined,
    signal: AbortSignal.timeout(input.timeoutMs)
  });
  if (!response.ok) {
    const detail = (await response.text()).trim().slice(0, 300);
    throw new Error(`CLIProxyAPI reasoning-level discovery failed with HTTP ${response.status}${detail ? `: ${detail}` : ""}`);
  }
  return parseReasoningEffortCatalog(await response.json());
}
async function discoverModels(input) {
  const response = await (input.fetcher ?? fetch)(`${input.baseURL}/models`, {
    headers: input.apiKey ? { Authorization: `Bearer ${input.apiKey}` } : undefined,
    signal: AbortSignal.timeout(input.timeoutMs)
  });
  if (!response.ok) {
    const detail = (await response.text()).trim().slice(0, 300);
    throw new Error(`CLIProxyAPI model discovery failed with HTTP ${response.status}${detail ? `: ${detail}` : ""}`);
  }
  return parseCatalog(await response.json());
}
function parseModelProtocolCatalog(input) {
  if (!isRecord(input))
    throw new Error("Model metadata service returned a non-object catalog");
  return Object.fromEntries(Object.entries(input).flatMap(([providerID, provider]) => {
    if (!isRecord(provider))
      return [];
    const models = Object.fromEntries(Object.entries(isRecord(provider.models) ? provider.models : {}).flatMap(([modelID, model]) => {
      if (!isRecord(model) || !isRecord(model.provider) || typeof model.provider.npm !== "string") {
        return [];
      }
      return [[modelID, model.provider.npm]];
    }));
    const npm = typeof provider.npm === "string" ? provider.npm : undefined;
    return npm || Object.keys(models).length > 0 ? [[providerID, { ...npm ? { npm } : {}, models }]] : [];
  }));
}
async function discoverModelProtocols(input) {
  const response = await (input.fetcher ?? fetch)(input.url, {
    signal: AbortSignal.timeout(input.timeoutMs)
  });
  if (!response.ok) {
    const detail = (await response.text()).trim().slice(0, 300);
    throw new Error(`Model protocol discovery failed with HTTP ${response.status}${detail ? `: ${detail}` : ""}`);
  }
  return parseModelProtocolCatalog(await response.json());
}
function isPositiveNumber(value) {
  return typeof value === "number" && Number.isFinite(value) && value > 0;
}
function isRecord(value) {
  return typeof value === "object" && value !== null && !Array.isArray(value);
}

// src/shared.ts
var DEFAULT_BASE_URL = "http://localhost:8317/v1";
var DEFAULT_PROVIDER_ID = "cliproxyapi";
var DEFAULT_PROVIDER_NAME = "CLIProxyAPI";
var DEFAULT_DISCOVERY_TIMEOUT_MS = 1e4;
var DEFAULT_MODEL_METADATA_URL = "https://models.dev/api.json";
var DEFAULT_CONTEXT_LIMIT = 128000;
var DEFAULT_OUTPUT_LIMIT = 32000;
var V1_CHAT_PACKAGE = "@ai-sdk/openai-compatible";
var V1_RESPONSES_PACKAGE = "@ai-sdk/openai";
var V1_ANTHROPIC_PACKAGE = "@ai-sdk/anthropic";
var V2_CHAT_PACKAGE = "@opencode/ai/providers/openai-compatible";
var V2_RESPONSES_PACKAGE = "@opencode/ai/providers/openai";
var V2_ANTHROPIC_PACKAGE = "@opencode/ai/providers/anthropic";
function readOptions(input) {
  if (!input)
    return {};
  return {
    baseURL: stringOption(input.baseURL),
    apiKey: stringOption(input.apiKey),
    providerID: stringOption(input.providerID),
    providerName: stringOption(input.providerName),
    protocol: input.protocol === "responses" ? "responses" : input.protocol === "chat" ? "chat" : undefined,
    modelMetadataURL: input.modelMetadataURL === false ? false : stringOption(input.modelMetadataURL),
    discoveryTimeoutMs: typeof input.discoveryTimeoutMs === "number" && input.discoveryTimeoutMs > 0 ? input.discoveryTimeoutMs : undefined
  };
}
function stringOption(value) {
  return typeof value === "string" && value.trim() !== "" ? value : undefined;
}
function resolveModelLimits(model, effortCatalog) {
  const limit = effortCatalog[model.id]?.limit;
  return {
    context: limit?.context ?? DEFAULT_CONTEXT_LIMIT,
    output: limit?.output ?? DEFAULT_OUTPUT_LIMIT
  };
}
function isProperString(value) {
  return typeof value === "string" && value.trim() !== "";
}
function isProperBoolean(value) {
  return typeof value === "boolean";
}
function isProperContextLimit(value) {
  return Number.isInteger(value) && value > 0;
}
function isProperOutputLimit(value) {
  return Number.isInteger(value) && value > 0;
}
function properLimitOverrides(userLimit) {
  const input = typeof userLimit === "object" && userLimit !== null ? userLimit : {};
  return {
    ...isProperContextLimit(input.context) ? { context: input.context } : {},
    ...isProperOutputLimit(input.output) ? { output: input.output } : {}
  };
}
function definedKeys(value) {
  return Object.fromEntries(Object.entries(value).filter(([, item]) => item !== undefined));
}
function displayName(modelID) {
  return modelID.split("-").map((part) => {
    const lower = part.toLowerCase();
    if (lower === "gpt")
      return "GPT";
    if (lower === "oss")
      return "OSS";
    if (lower === "codex")
      return "Codex";
    return part.charAt(0).toUpperCase() + part.slice(1);
  }).join(" ");
}
function isImageModel(modelID) {
  return /(?:^|-)image(?:-|$)/i.test(modelID);
}
function isReasoningModel(modelID, efforts) {
  if (efforts?.levels?.length)
    return efforts.levels.some((level) => level !== "none");
  return /thinking|reasoning|codex|gpt-(?:5|oss)/i.test(modelID);
}
function supportsAttachments(modelID) {
  return /^(?:claude|gemini|gpt)/i.test(modelID) && !/^gpt-oss(?:-|$)/i.test(modelID);
}
function modelModalities(modelID) {
  const imageOutput = isImageModel(modelID);
  return {
    input: imageOutput || supportsAttachments(modelID) ? ["text", "image"] : ["text"],
    output: imageOutput ? ["image"] : ["text"]
  };
}
function resolveModelNpm(catalog, providerID, modelID) {
  const provider = catalog[providerID];
  return provider?.models[modelID] ?? provider?.npm;
}
function isAnthropicRouted(model, protocolCatalog) {
  return model.ownedBy !== undefined && resolveModelNpm(protocolCatalog, model.ownedBy, model.id) === V1_ANTHROPIC_PACKAGE;
}
function supportedEffortLevels(model, input) {
  const efforts = input.effortCatalog[model.id];
  if (!efforts)
    return;
  if (isAnthropicRouted(model, input.protocolCatalog))
    return;
  const levels = efforts.levels?.filter((level) => level !== "none") ?? [];
  return levels.length > 0 ? levels : undefined;
}
async function discoverCatalog(input) {
  const [catalog, protocolDiscovery, effortDiscovery] = await Promise.all([
    discoverModels({ baseURL: input.baseURL, apiKey: input.apiKey, timeoutMs: input.timeoutMs }),
    discoverProtocols({ url: input.modelMetadataURL, timeoutMs: input.timeoutMs }),
    discoverEffortLevels({ baseURL: input.baseURL, apiKey: input.apiKey, timeoutMs: input.timeoutMs })
  ]);
  return {
    catalog,
    protocolCatalog: protocolDiscovery.catalog,
    effortCatalog: effortDiscovery.catalog,
    errors: [protocolDiscovery.error, effortDiscovery.error].filter((error) => error !== undefined)
  };
}
function discoverProtocols(input) {
  if (input.url === false)
    return Promise.resolve({ catalog: {} });
  return discoverModelProtocols({
    url: input.url,
    timeoutMs: input.timeoutMs
  }).then((catalog) => ({ catalog })).catch((error) => ({
    catalog: {},
    error: error instanceof Error ? error.message : String(error)
  }));
}
function discoverEffortLevels(input) {
  return discoverReasoningEfforts(input).then((catalog) => ({ catalog })).catch((error) => ({
    catalog: {},
    error: error instanceof Error ? error.message : String(error)
  }));
}

// src/plugin-v2.ts
function toV2Model(model, input) {
  const image = isImageModel(model.id);
  const modalities = modelModalities(model.id);
  const levels = supportedEffortLevels(model, input.discovery);
  const anthropic = isAnthropicRouted(model, input.discovery.protocolCatalog);
  return {
    id: model.id,
    modelID: model.id,
    providerID: input.providerID,
    name: displayName(model.id),
    ...anthropic ? { package: V2_ANTHROPIC_PACKAGE } : {},
    capabilities: {
      tools: !image,
      input: modalities.input,
      output: modalities.output
    },
    variants: (levels ?? []).map((level) => ({
      id: level,
      settings: { reasoningEffort: level }
    })),
    time: { released: 0 },
    cost: [{ input: 0, output: 0, cache: { read: 0, write: 0 } }],
    status: "active",
    enabled: true,
    limit: resolveModelLimits(model, input.discovery.effortCatalog)
  };
}
function toV2Models(input) {
  return input.discovery.catalog.map((model) => toV2Model(model, { providerID: input.providerID, discovery: input.discovery }));
}
function mergeV2Models(discovered, userModels) {
  const merged = discovered.map((base) => {
    const userModel = userModels?.get(base.id);
    return isRecord2(userModel) ? mergeV2Model(base, userModel) : base;
  });
  if (userModels) {
    const discoveredIDs = new Set(discovered.map((model) => model.id));
    for (const [id, userModel] of userModels) {
      if (!discoveredIDs.has(id) && isRecord2(userModel))
        merged.push(userModel);
    }
  }
  return merged;
}
function mergeV2Model(base, userModel) {
  return {
    ...base,
    ...definedKeys(userModel),
    name: isProperString(userModel.name) ? userModel.name : base.name,
    package: isProperString(userModel.package) ? userModel.package : base.package,
    enabled: isProperBoolean(userModel.enabled) ? userModel.enabled : base.enabled,
    limit: { ...base.limit, ...properLimitOverrides(userModel.limit) }
  };
}
function isRecord2(value) {
  return typeof value === "object" && value !== null && !Array.isArray(value);
}
async function setup(ctx) {
  const options = readOptions(ctx.options);
  const providerID = options.providerID ?? DEFAULT_PROVIDER_ID;
  const baseURL = normalizeBaseURL(options.baseURL ?? process.env.CLIPROXY_BASE_URL ?? DEFAULT_BASE_URL);
  const apiKey = options.apiKey ?? process.env.CLIPROXY_API_KEY;
  const timeoutMs = options.discoveryTimeoutMs ?? DEFAULT_DISCOVERY_TIMEOUT_MS;
  const modelMetadataURL = options.modelMetadataURL ?? DEFAULT_MODEL_METADATA_URL;
  const discovery = await discoverCatalog({ baseURL, apiKey, modelMetadataURL, timeoutMs });
  for (const error of discovery.errors) {
    console.warn(`[cliproxyapi] ${error}`);
  }
  const discovered = toV2Models({ providerID, discovery });
  const providerPackage = options.protocol === "responses" ? V2_RESPONSES_PACKAGE : V2_CHAT_PACKAGE;
  await ctx.provider.transform((editor) => {
    const settings = { baseURL };
    if (apiKey)
      settings.apiKey = apiKey;
    const existing = editor.get(providerID);
    const models = mergeV2Models(discovered, existing?.models);
    if (existing) {
      editor.update(providerID, (provider) => {
        provider.name = provider.name || options.providerName || DEFAULT_PROVIDER_NAME;
        provider.activation = "enabled";
        provider.package = providerPackage;
        provider.settings = { ...provider.settings, ...settings };
      });
      editor.models.set(providerID, models);
      return;
    }
    const info = {
      id: providerID,
      name: options.providerName ?? DEFAULT_PROVIDER_NAME,
      activation: "enabled",
      package: providerPackage,
      settings
    };
    editor.add({ info, models });
  });
  return async () => {};
}

// src/index.ts
var CLIProxyAPIPlugin = async ({ client }, rawOptions) => {
  const options = readOptions(rawOptions);
  return {
    config: async (config) => {
      const providerID = options.providerID ?? DEFAULT_PROVIDER_ID;
      const existing = config.provider?.[providerID];
      const baseURL = normalizeBaseURL(options.baseURL ?? process.env.CLIPROXY_BASE_URL ?? stringOption(existing?.options?.baseURL) ?? DEFAULT_BASE_URL);
      const apiKey = options.apiKey ?? process.env.CLIPROXY_API_KEY ?? stringOption(existing?.options?.apiKey);
      try {
        const timeoutMs = options.discoveryTimeoutMs ?? DEFAULT_DISCOVERY_TIMEOUT_MS;
        const discovery = await discoverCatalog({
          baseURL,
          apiKey,
          modelMetadataURL: options.modelMetadataURL ?? DEFAULT_MODEL_METADATA_URL,
          timeoutMs
        });
        for (const message of discovery.errors) {
          await client.app.log({
            body: {
              service: "opencode-cliproxyapi",
              level: "warn",
              message
            }
          });
        }
        addProvider(config, {
          providerID,
          providerName: options.providerName ?? DEFAULT_PROVIDER_NAME,
          baseURL,
          apiKey,
          protocol: options.protocol ?? "chat",
          catalog: discovery.catalog,
          protocolCatalog: discovery.protocolCatalog,
          effortCatalog: discovery.effortCatalog
        });
        await client.app.log({
          body: {
            service: "opencode-cliproxyapi",
            level: "info",
            message: `Discovered ${discovery.catalog.length} CLIProxyAPI models from ${baseURL}`
          }
        });
      } catch (error) {
        await client.app.log({
          body: {
            service: "opencode-cliproxyapi",
            level: "error",
            message: error instanceof Error ? error.message : String(error)
          }
        });
        throw error;
      }
    }
  };
};
var src_default = {
  id: "opencode-cliproxyapi",
  server: CLIProxyAPIPlugin,
  setup
};
function addProvider(config, input) {
  const existing = config.provider?.[input.providerID];
  const discovered = Object.fromEntries(input.catalog.map((model) => [
    model.id,
    {
      name: displayName(model.id),
      tool_call: !isImageModel(model.id),
      reasoning: isReasoningModel(model.id, input.effortCatalog[model.id]),
      attachment: supportsAttachments(model.id),
      limit: resolveModelLimits(model, input.effortCatalog),
      ...model.ownedBy && resolveModelNpm(input.protocolCatalog, model.ownedBy, model.id) === V1_ANTHROPIC_PACKAGE ? {
        provider: {
          npm: V1_ANTHROPIC_PACKAGE
        }
      } : {},
      ...imageModalities(model.id),
      ...reasoningEffortConfig(model, input)
    }
  ]));
  config.provider = {
    ...config.provider,
    [input.providerID]: {
      ...existing,
      name: existing?.name ?? input.providerName,
      npm: existing?.npm ?? (input.protocol === "responses" ? V1_RESPONSES_PACKAGE : V1_CHAT_PACKAGE),
      env: [...new Set([...existing?.env ?? [], "CLIPROXY_API_KEY"])],
      options: {
        ...existing?.options,
        baseURL: input.baseURL,
        ...input.apiKey ? { apiKey: input.apiKey } : {}
      },
      models: mergeModels(discovered, existing?.models)
    }
  };
}
function imageModalities(modelID) {
  const modalities = modelModalities(modelID);
  if (!modalities.input.includes("image") && !modalities.output.includes("image"))
    return {};
  return { modalities };
}
function reasoningEffortConfig(model, input) {
  const efforts = input.effortCatalog[model.id];
  if (!efforts)
    return {};
  const levels = supportedEffortLevels(model, input);
  if (!levels)
    return {};
  const defaultLevel = efforts.defaultLevel !== undefined && efforts.levels?.includes(efforts.defaultLevel) ? efforts.defaultLevel : undefined;
  return {
    ...defaultLevel ? { options: { reasoningEffort: defaultLevel } } : {},
    variants: {
      ...Object.fromEntries((efforts.levels ?? []).map((level) => [level, { reasoningEffort: level }])),
      ...disabledVariants(efforts.levels ?? [])
    }
  };
}
var OPENCODE_DEFAULT_EFFORTS = ["none", "minimal", "low", "medium", "high", "xhigh", "max", "ultra"];
function disabledVariants(supported) {
  const supportedSet = new Set(supported);
  return Object.fromEntries(OPENCODE_DEFAULT_EFFORTS.filter((effort) => !supportedSet.has(effort)).map((effort) => [
    effort,
    { disabled: true }
  ]));
}
function mergeModels(discovered, existing) {
  const merged = { ...discovered };
  for (const [modelID, userModel] of Object.entries(existing ?? {})) {
    const base = merged[modelID];
    if (!base) {
      if (isRecord3(userModel))
        merged[modelID] = { ...userModel };
      continue;
    }
    if (isRecord3(userModel))
      merged[modelID] = mergeDiscoveredModel(base, userModel);
  }
  return merged;
}
function mergeDiscoveredModel(base, userModel) {
  const limits = { ...base.limit, ...properLimitOverrides(userModel.limit) };
  const merged = {
    ...base,
    ...definedKeys(userModel),
    name: isProperString(userModel.name) ? userModel.name : base.name,
    tool_call: isProperBoolean(userModel.tool_call) ? userModel.tool_call : base.tool_call,
    reasoning: isProperBoolean(userModel.reasoning) ? userModel.reasoning : base.reasoning,
    attachment: isProperBoolean(userModel.attachment) ? userModel.attachment : base.attachment,
    limit: limits
  };
  const userProvider = userModel.provider;
  if (typeof userProvider === "object" && userProvider !== null) {
    const { npm, ...rest } = userProvider;
    const providerNpm = isProperString(npm) ? npm : base.provider?.npm;
    const provider = providerNpm ? { npm: providerNpm, ...rest } : rest;
    if (Object.keys(provider ?? {}).length > 0)
      merged.provider = provider;
  }
  return merged;
}
function isRecord3(value) {
  return typeof value === "object" && value !== null && !Array.isArray(value);
}
export {
  CLIProxyAPIPlugin,
  src_default as default,
  discoverModelProtocols,
  discoverModels,
  discoverReasoningEfforts,
  normalizeBaseURL,
  parseCatalog,
  parseModelProtocolCatalog,
  parseReasoningEffortCatalog
};
